exports.selectFrame = (progress, count, options = {}) => {
  if (!Number.isInteger(count) || count <= 0) return null;
  if (options.reducedMotion === true || options.visible === false) return 0;
  const value = typeof progress === 'number' && Number.isFinite(progress) ? progress : 0;
  return Math.floor(Math.max(0, Math.min(1, value)) * (count - 1));
};

const test = require('node:test');
const assert = require('node:assert/strict');
const { currentAsset } = require('../src/page.cjs');
test('reduced motion stays static and absent assets stay a placeholder', () => {
  assert.equal(currentAsset(1,['first','last'],{reducedMotion:true}),'first');
  assert.equal(currentAsset(1,[],{}),'placeholder');
});
